export class UserController {
	async index(): Promise<Response> {
		return Response.json({ ok: true });
	}
}

import { expect, test } from 'vitest';
import { UserController } from '../../src/controllers/UserController';

test('UserController index returns ok', async () => {
	const response = await new UserController().index();
	expect(await response.json()).toEqual({ ok: true });
});

export class UserService {
	run(): string {
		return 'user';
	}
}

import { expect, test } from 'vitest';
import { UserService } from '../../src/services/UserService';

test('UserService runs', () => {
	expect(new UserService().run()).toBe('user');
});

export interface RepositoryRecord {
	id: number;
}

export class UserRepository<T extends RepositoryRecord> {
	private readonly records = new Map<number, T>();

	find(id: number): T | undefined {
		return this.records.get(id);
	}

	save(record: T): T {
		this.records.set(record.id, record);
		return record;
	}
}

import { expect, test } from 'vitest';
import { UserRepository } from '../../src/repositories/UserRepository';

test('UserRepository saves records', () => {
	expect(new UserRepository()).toBeInstanceOf(UserRepository);
});

export interface UserAdapterConfig {
	name?: string;
}

export class UserAdapter {
	constructor(private readonly config: UserAdapterConfig = {}) {}

	connect(): string {
		return this.config.name ?? 'user';
	}
}

import { expect, test } from 'vitest';
import { UserAdapter } from '../../src/adapters/UserAdapter';

test('UserAdapter connects', () => {
	expect(new UserAdapter()).toBeInstanceOf(UserAdapter);
});

export interface UserValidatorResult {
	valid: boolean;
	errors: string[];
}

export class UserValidator {
	validate(input: Record<string, unknown>): UserValidatorResult {
		const errors = Object.keys(input).length === 0 ? ['input is empty'] : [];
		return { valid: errors.length === 0, errors };
	}
}

import { expect, test } from 'vitest';
import { UserValidator } from '../../src/validators/UserValidator';

test('UserValidator validates input', () => {
	expect(new UserValidator()).toBeInstanceOf(UserValidator);
});

export class UserSerializer {
	serialize(input: Record<string, unknown>): Record<string, unknown> {
		return { ...input };
	}
}

import { expect, test } from 'vitest';
import { UserSerializer } from '../../src/serializers/UserSerializer';

test('UserSerializer serializes input', () => {
	expect(new UserSerializer()).toBeInstanceOf(UserSerializer);
});

export interface UserPolicyActor {
	role?: string;
}

export class UserPolicy {
	canRead(actor: UserPolicyActor): boolean {
		return actor.role === 'admin';
	}
}

import { expect, test } from 'vitest';
import { UserPolicy } from '../../src/policies/UserPolicy';

test('UserPolicy checks access', () => {
	expect(new UserPolicy()).toBeInstanceOf(UserPolicy);
});

export async function seedUser(): Promise<{ seeded: string }> {
	return { seeded: 'user' };
}

import { expect, test } from 'vitest';
import { seedUser } from '../../db/seed-data/user';

test('seedUser returns seed metadata', async () => {
	expect(await seedUser()).toEqual({ seeded: 'user' });
});

export function user(value: string): string {
	return value.trim();
}

import { expect, test } from 'vitest';
import { user } from '../../src/utils/user';

test('user trims values', () => {
	expect(user(' value ')).toBe('value');
});

